@startuml

class Line {
  + Name
}

class Piece {
  + Type
  + Ref
  + Price
}

class Component {
  + Code
  + Price
  + Type
}

class Store {
  + Name
  + Address
  + FAX
}

class Order {
  + Number
  + Date
}

class PieceComponent {
  + Quantity
}

class PieceOrder {
  + Quantity
}

Line "1" -- "*" Piece
Piece "*" -- "1" Line
Component "*" -- "*" Piece
Piece "1" -- "1..*" PieceComponent
PieceComponent "*" -- "1" Component
Store "1" -- "*" Order
Order "*" -- "1" Store
Order "1" -- "*" PieceOrder
PieceOrder "*" -- "1" Piece

@enduml

